    var apply = btn("btn im-apply", t("apply"), "i-wand"); apply.id="imApply"; apply.onclick=function(){ applyOne(S.cur); }; off(apply, S.busy); acts.appendChild(apply);
    if(S.photos.length>1){ var all = btn("btn im-applyall", t("apply_all"), "i-stack"); all.id="imApplyAll"; all.onclick=applyAll; off(all, S.busy); acts.appendChild(all); }
    var exp = btn("btn im-export", t("export"), "i-download"); exp.id="imExport"; exp.onclick=exportCur; acts.appendChild(exp);
    if(S.busy){ var stop = btn("btn im-stop", t("stop"), "i-close"); stop.id="imStop"; stop.onclick=stopAll; acts.appendChild(stop); }
    if(S.photos.length && !S.busy){ var clr = btn("btn im-clear", t("clear"), "i-trash"); clr.id="imClear"; clr.onclick=clearAll; acts.appendChild(clr); }
